# hypothesis: Assigning to a ReadOnly TypedDict key is a checker error, while CPython treats the TypedDict as a plain dict and applies the write.
from typing import NotRequired, ReadOnly, TypedDict, Unpack, reveal_type


class Config(TypedDict):
    name: ReadOnly[str]
    retries: NotRequired[int]


def make(**kwargs: Unpack[Config]) -> Config:
    return kwargs


def describe(cfg: Config) -> str:
    return cfg['name'] + ':' + str(cfg.get('retries', 0))


def rename(cfg: Config) -> None:
    cfg['name'] = 'other'  # expect-error: 'name' is ReadOnly
    print('renamed', cfg['name'])


def drop_retries(cfg: Config) -> int:
    del cfg['retries']  # NotRequired key may be deleted
    return len(cfg)


def missing_name() -> None:
    bad = make(retries=1)  # expect-error: missing required key 'name'
    try:
        print('bad', describe(bad))
    except KeyError as e:
        print('keyerror', e)


cfg = make(name='api', retries=3)
reveal_type(cfg.get('retries'))
print(describe(cfg))
rename(cfg)
print(describe(cfg))
print('after del', drop_retries(cfg))
print(describe(cfg))
missing_name()
